#!/bin/bash

print_dry_run_plan() {
  log "[dry-run] version=$V"
  log "[dry-run] dmg=$DMG (and $DMG.sha256)"
  log "[dry-run] app=$APP"
  log "[dry-run] state=$STATE"
  log "[dry-run] plist=$PLIST"
  log "[dry-run] would run scripts/deploy/launcher-app-check.sh launcher and refuse unless $APP started tmux (unknown is a refusal unless --allow-unknown-launcher; allow_unknown_launcher=$ALLOW_UNKNOWN_LAUNCHER)"
  log "[dry-run] would, after the install, fail loudly if /Applications holds a 'Carnivore <version>.app'"
  log "[dry-run] would verify sha256 of \$dmg against \$dmg.sha256"
  log "[dry-run] would snapshot 'tmux -L cloude list-sessions' to ${TMPDIR:-/tmp}/deploy-$TS.before"
  log "[dry-run] would back up \$state/carnivore.db (cloude.db only if it is the sole database) to $BACKUP_DIR and run PRAGMA quick_check"
  log "[dry-run] would mount \$dmg and verify codesign against the requirement READ from \$app (accepted signers: that one, $DEVID_REQ, $REQ)"
  log "[dry-run] would refuse a different signer unless --allow-signer-change (allow_signer_change=$ALLOW_SIGNER_CHANGE): privacy grants do not carry over"
  log "[dry-run] would read the currently-installed version from \$app/Contents/Info.plist"
  log "[dry-run] would refuse if $ROLLBACK_DIR/Carnivore <current version>.app already exists"
  log "[dry-run] would bootout $LABEL AND any stray application.ai.carnivore.menubar.* job"
  log "[dry-run] would, on a refusal or failure after that stop and before the swap, start the previous app again through the same launchctl bootstrap the install uses (nothing was moved), then exit non-zero with the reason; after the swap the rollback runs instead"
  log "[dry-run] would SIGTERM (never SIGKILL; a survivor makes the port wait refuse) a detached engine holding :8000 ONLY when it is a -m src.main run by $USER from $ENGINE_DIR; any other holder, or a port that answers a connect probe on 127.0.0.1/[::1] with no holder of ours, refuses (exit 2); the rollback runs the same stop plus a sweep of that user's port-less -m src.main processes from $ENGINE_DIR"
  log "[dry-run] would wait (bounded) for :8000 to be free, naming the holder pid+comm if stuck"
  log "[dry-run] would ditto the new app into $STAGED_APP and re-verify its signature BEFORE stopping anything"
  log "[dry-run] would, before stopping anything, run $SWAP_HELPER --check on \$app/Contents and $STAGED_APP/Contents (both directories, same volume, renamex_np available) and refuse if it fails"
  log "[dry-run] would exchange \$app/Contents and $STAGED_APP/Contents in ONE atomic renamex_np(RENAME_SWAP) (the bundle keeps its name and path and is never without code; a failed exchange moves nothing), move the old Contents to $OLD, keep them as $ROLLBACK_DIR/Carnivore <current>.app, bootstrap \$plist"
  log "[dry-run] would re-check for a stray job that reappeared during startup"
  log "[dry-run] would wait for :8000 to answer v$V FROM A CHILD of the new job's own pid"
  log "[dry-run] would diff the tmux session list before/after and fail on any change"
  log "[dry-run] would then check the backup drive $DRIVE_ROOT: list it, create and remove one probe file; refused (EPERM/EACCES) exits $EXIT_DRIVE_REFUSED naming v$V, the time and the fix (switch Carnivore off and on in Full Disk Access); not mounted is 'skipped: not mounted'; reports whether this shell is inside the tmux -L cloude tree; sends nothing to tmux"
  log "[dry-run] nothing was read from or written to disk"
}
